import{c as t,Q as a,j as i,m as s}from"./chunks/framework.DoOjWOm2.js";const m=JSON.parse('{"title":"Movies Library Setup","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/movies.md","filePath":"libraries/movies.md"}'),o={name:"libraries/movies.md"};function r(n,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="movies-library-setup" tabindex="-1">Movies Library Setup <a class="header-anchor" href="#movies-library-setup" aria-label="Permalink to &quot;Movies Library Setup&quot;">​</a></h1><p><strong>Step:</strong> N.7 <strong>Since:</strong> 0.14.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>A movies library turns your video collection into a browsable, searchable catalog with posters, synopses, and cast info pulled from online databases. Drop your video files into a folder, add that folder to Phlix as a Movies library, and Phlix handles the rest — matching titles, fetching artwork, and tracking your watch progress across devices.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add your movies folder, scan, and you&#39;re ready</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Libraries → Add Library → Type: Movies → point to /path/to/movies → Scan</span></span></code></pre></div><h2 id="_1-supported-formats" tabindex="-1">1. Supported Formats <a class="header-anchor" href="#_1-supported-formats" aria-label="Permalink to &quot;1. Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>Playback Notes</th></tr></thead><tbody><tr><td>Matroska</td><td><code>.mkv</code></td><td>Most common; supports many codecs</td></tr><tr><td>MPEG-4</td><td><code>.mp4</code>, <code>.m4v</code></td><td>Wide device compatibility</td></tr><tr><td>AVI</td><td><code>.avi</code></td><td>Legacy format; some files may need transcoding</td></tr><tr><td>QuickTime</td><td><code>.mov</code></td><td>Common for iTunes content</td></tr><tr><td>Windows Media</td><td><code>.wmv</code></td><td>May require transcoding on non-Windows clients</td></tr><tr><td>MPEG Transport Stream</td><td><code>.ts</code></td><td>Used for broadcast recordings</td></tr></tbody></table><p>Container format matters less than the codec inside. Phlix streams directly when your player supports the codec; transcoding falls back automatically when needed.</p><h2 id="_2-naming-conventions" tabindex="-1">2. Naming Conventions <a class="header-anchor" href="#_2-naming-conventions" aria-label="Permalink to &quot;2. Naming Conventions&quot;">​</a></h2><h3 id="_2a-flat-file-naming-simplest" tabindex="-1">2a. Flat-File Naming (Simplest) <a class="header-anchor" href="#_2a-flat-file-naming-simplest" aria-label="Permalink to &quot;2a. Flat-File Naming (Simplest)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avatar (2009).mkv</span></span>
<span class="line"><span>The Matrix (1999).mp4</span></span></code></pre></div><ul><li><code>Movie Name (Year).ext</code> — Phlix uses the year in parentheses as the primary identifier for metadata matching</li><li>Year range accepted by the scanner: 1900 through 5 years in the future</li></ul><h3 id="_2b-folder-based-naming" tabindex="-1">2b. Folder-Based Naming <a class="header-anchor" href="#_2b-folder-based-naming" aria-label="Permalink to &quot;2b. Folder-Based Naming&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/Movies/</span></span>
<span class="line"><span>  The Matrix (1999)/</span></span>
<span class="line"><span>    Matrix, The.mp4</span></span>
<span class="line"><span>  Avatar (2009)/</span></span>
<span class="line"><span>    Avatar.mkv</span></span></code></pre></div><ul><li>Folder name follows <code>Movie Name (Year)/</code> — the article (&quot;The&quot;, &quot;A&quot;, &quot;An&quot;) sorts to the end of the folder name: <code>The Matrix</code> becomes <code>Matrix, The</code></li><li>The video file inside can be named anything; the folder name is what matters</li></ul><h3 id="_2c-multi-version-movies" tabindex="-1">2c. Multi-Version Movies <a class="header-anchor" href="#_2c-multi-version-movies" aria-label="Permalink to &quot;2c. Multi-Version Movies&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avatar (2009) - directors-cut.mkv</span></span>
<span class="line"><span>Avatar (2009) - extended.mkv</span></span>
<span class="line"><span>Avatar (2009) - 4k-restored.mkv</span></span></code></pre></div><ul><li>A version tag (<code> - directors-cut</code>, <code> - extended</code>, <code> - 4k-restored</code>) after the year creates a separate library entry per version</li><li>Each version has its own playback state and resume position</li></ul><h3 id="_2d-disc-folder-structure" tabindex="-1">2d. Disc Folder Structure <a class="header-anchor" href="#_2d-disc-folder-structure" aria-label="Permalink to &quot;2d. Disc Folder Structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Movie Name (2020)/</span></span>
<span class="line"><span>  movie.mkv</span></span>
<span class="line"><span>  trailer.mkv</span></span>
<span class="line"><span>  extras/</span></span>
<span class="line"><span>    Behind the Scenes.mkv</span></span></code></pre></div><ul><li><code>movie.mkv</code> is the main feature; files named <code>-trailer</code> or <code>-sample</code> are excluded from the main library count but associated with the item</li><li>The <code>extras/</code> subfolder is scanned as associated extras; naming inside is free-form</li></ul><h2 id="_3-nfo-sidecar-files" tabindex="-1">3. NFO Sidecar Files <a class="header-anchor" href="#_3-nfo-sidecar-files" aria-label="Permalink to &quot;3. NFO Sidecar Files&quot;">​</a></h2><p>Kodi-style NFO files let you lock metadata to a specific online record or add custom local data.</p><h3 id="per-movie-nfo" tabindex="-1">Per-Movie NFO <a class="header-anchor" href="#per-movie-nfo" aria-label="Permalink to &quot;Per-Movie NFO&quot;">​</a></h3><p>Place <code>movie.nfo</code> alongside the video file:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">movie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Avatar&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2009&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tmdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;241&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tmdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Jake Sully lives with the Na&#39;vi on Pandora...&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">movie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><code>tmdbid</code> is the primary lookup key — when present, Phlix fetches metadata directly from TMDB without title/year matching</li><li>Local NFO always takes priority when <code>metadata_source</code> is set to <code>local</code> in the library configuration</li><li>The filename is <strong>case-sensitive</strong> on Linux: must be exactly <code>movie.nfo</code>, not <code>Movie.nfo</code> or <code>MOVIE.NFO</code></li></ul><h3 id="what-goes-in-an-nfo" tabindex="-1">What Goes in an NFO <a class="header-anchor" href="#what-goes-in-an-nfo" aria-label="Permalink to &quot;What Goes in an NFO&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Movie title</td></tr><tr><td><code>year</code></td><td>Release year (4 digits)</td></tr><tr><td><code>tmdbid</code></td><td>TMDB movie ID (e.g., <code>241</code> for Avatar)</td></tr><tr><td><code>tvdbid</code></td><td>TVDB ID (fallback)</td></tr><tr><td><code>plot</code></td><td>Synopsis text</td></tr><tr><td><code>genre</code></td><td>Genre tags</td></tr><tr><td><code>director</code></td><td>Director name</td></tr><tr><td><code>rating</code></td><td>Content rating (MPAA or custom)</td></tr></tbody></table><h2 id="_4-metadata-sources-and-priority" tabindex="-1">4. Metadata Sources and Priority <a class="header-anchor" href="#_4-metadata-sources-and-priority" aria-label="Permalink to &quot;4. Metadata Sources and Priority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Source</th><th>Notes</th></tr></thead><tbody><tr><td>1 (highest)</td><td>Local NFO</td><td><code>movie.nfo</code> in the same folder</td></tr><tr><td>2</td><td>TMDB</td><td>Primary online metadata; free account at themoviedb.org</td></tr><tr><td>3</td><td>TVDB</td><td>Fallback when TMDB has no match</td></tr><tr><td>4</td><td>Filename parsing</td><td>Year and title extracted from file/folder name as last resort</td></tr></tbody></table><p>Remote metadata is cached for 24 hours to avoid rate limiting. To refresh metadata immediately, click <strong>Refresh Metadata</strong> on any item in the UI. Adding a TMDB API key in library settings raises the rate limit.</p><h2 id="_5-scanner-behavior" tabindex="-1">5. Scanner Behavior <a class="header-anchor" href="#_5-scanner-behavior" aria-label="Permalink to &quot;5. Scanner Behavior&quot;">​</a></h2><h3 id="how-phlix-distinguishes-movies-from-tv-episodes" tabindex="-1">How Phlix Distinguishes Movies from TV Episodes <a class="header-anchor" href="#how-phlix-distinguishes-movies-from-tv-episodes" aria-label="Permalink to &quot;How Phlix Distinguishes Movies from TV Episodes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pattern in Filename</th><th>Classification</th><th>Example</th></tr></thead><tbody><tr><td><code>(Year)</code> only, no episode code</td><td>Movie</td><td><code>Avatar (2009).mkv</code></td></tr><tr><td><code>S01E01</code> or <code>1x01</code></td><td>TV episode</td><td><code>Show Name S01E01.mkv</code></td></tr><tr><td><code>Season 00/</code> or <code>Specials/</code> folder</td><td>TV (specials)</td><td><code>Season 00/</code></td></tr><tr><td>Both episode code AND year</td><td>TV (episode number wins)</td><td><code>Show (2020) S01E01.mkv</code></td></tr></tbody></table><h3 id="scan-triggering" tabindex="-1">Scan Triggering <a class="header-anchor" href="#scan-triggering" aria-label="Permalink to &quot;Scan Triggering&quot;">​</a></h3><ul><li><strong>Manual</strong>: Click <strong>Scan Library</strong> in the library&#39;s UI settings</li><li><strong>Automatic</strong>: Folder watcher detects <code>mtime</code> changes and queues an incremental rescan</li><li><strong>First add</strong>: Full recursive scan of the library root</li></ul><h3 id="incremental-rescans" tabindex="-1">Incremental Rescans <a class="header-anchor" href="#incremental-rescans" aria-label="Permalink to &quot;Incremental Rescans&quot;">​</a></h3><p>The scanner uses mtime-based checksums — only files whose modification time changed since the last scan are reprocessed. Show-level metadata (poster, fanart) is re-fetched only when <code>metadata_refreshed_at</code> is older than 24 hours.</p><h2 id="_6-content-rating-and-parental-controls" tabindex="-1">6. Content Rating and Parental Controls <a class="header-anchor" href="#_6-content-rating-and-parental-controls" aria-label="Permalink to &quot;6. Content Rating and Parental Controls&quot;">​</a></h2><p>Each user profile has a rating filter set in <strong>Settings → Profiles</strong>: G / PG / PG-13 / R / NC-17 / X / UNRATED. Movies rated above the profile&#39;s filter are hidden from that profile&#39;s library view.</p><ul><li>Ratings are pulled from TMDB or TVDB metadata</li><li>Items sourced from NFO without a rating default to UNRATED (visible to all profiles)</li><li>You can manually set a content rating on any item from the item detail page</li></ul><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="duplicate-entries-or-split-library" tabindex="-1">Duplicate Entries or Split Library <a class="header-anchor" href="#duplicate-entries-or-split-library" aria-label="Permalink to &quot;Duplicate Entries or Split Library&quot;">​</a></h3><p><strong>Symptom:</strong> The same movie appears 2–4 times in the library after a rescan.</p><p><strong>Cause:</strong> Mixing flat-file and folder-based naming for the same movie; inconsistent year in filenames.</p><p><strong>Fix:</strong> Pick one naming style per library. Run <strong>Empty Library</strong> from library settings, then re-scan. For multi-version movies, keep all versions in the same folder with distinct version tags.</p><hr><h3 id="metadata-not-found-or-wrong-match" tabindex="-1">Metadata Not Found or Wrong Match <a class="header-anchor" href="#metadata-not-found-or-wrong-match" aria-label="Permalink to &quot;Metadata Not Found or Wrong Match&quot;">​</a></h3><p><strong>Symptom:</strong> Movie shows as &quot;Unknown Title&quot; or matches a different film.</p><p><strong>Cause:</strong> Year mismatch between your filename and the TMDB record; special characters or non-English titles break parsing.</p><p><strong>Fix:</strong> Rename the file to <code>Movie Name (Year).ext</code> with the exact year from TMDB. Or create a <code>movie.nfo</code> with the correct <code>tmdbid</code> to bypass title/year matching entirely.</p><hr><h3 id="nfo-file-ignored" tabindex="-1">NFO File Ignored <a class="header-anchor" href="#nfo-file-ignored" aria-label="Permalink to &quot;NFO File Ignored&quot;">​</a></h3><p><strong>Symptom:</strong> Custom poster, plot, or genre tags from your NFO are not appearing in Phlix.</p><p><strong>Cause:</strong> NFO filename is not exactly <code>movie.nfo</code> (Linux is case-sensitive), or the NFO file contains malformed XML.</p><p><strong>Fix:</strong> Rename to <code>movie.nfo</code> with a lowercase <code>m</code>. Validate your XML at <a href="https://www.xmlvalidation.com" target="_blank" rel="noreferrer">xmlvalidation.com</a>. Ensure the root element is <code>&lt;movie&gt;</code>.</p><hr><h3 id="metadata-fetch-failure-or-rate-limit" tabindex="-1">Metadata Fetch Failure or Rate Limit <a class="header-anchor" href="#metadata-fetch-failure-or-rate-limit" aria-label="Permalink to &quot;Metadata Fetch Failure or Rate Limit&quot;">​</a></h3><p><strong>Symptom:</strong> Newly scanned movies show &quot;No metadata&quot; despite correct filenames.</p><p><strong>Cause:</strong> TMDB API rate limit exceeded, or the server cannot reach TMDB.</p><p><strong>Fix:</strong> Wait 10 seconds and click <strong>Refresh Metadata</strong> on the item. For large initial scans, add a TMDB API key in library settings. Check server network connectivity to <code>api.themoviedb.org</code>.</p><hr><h3 id="parental-control-content-leaking-through" tabindex="-1">Parental Control Content Leaking Through <a class="header-anchor" href="#parental-control-content-leaking-through" aria-label="Permalink to &quot;Parental Control Content Leaking Through&quot;">​</a></h3><p><strong>Symptom:</strong> Restricted content is visible on a child profile.</p><p><strong>Cause:</strong> Profile rating filter set too high; or the media item has UNRATED metadata and is not filtered.</p><p><strong>Fix:</strong> Lower the profile&#39;s rating filter in <strong>Settings → Profiles</strong>. From the item&#39;s detail page, manually set the content rating if it shows as UNRATED.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./tv-shows.html">TV Shows library setup</a> — organize episodes by season with S01E01 naming</li><li><a href="./music.html">Music library setup</a> — album art, FLAC/MP3 tagging, compiled albums</li><li><a href="./../users/dlna.html">DLNA / Play To</a> — stream movies to DLNA-compatible TVs and speakers</li></ul>`,69)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
